function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 300) return 'grid needs 1 to 300 rows.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1 || n > 300) return 'Each row needs 1 to 300 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

