function removeOnes(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const colFlip = new Array(n).fill(0);
  // Try every set of flipped columns; then each row must be all 0s or all 1s (flip the all-1 rows).
  const tryColumns = (c) => {
    if (c === n) {
      for (let r = 0; r < m; r++) {
        const values = new Set(grid[r].map((v, j) => v ^ colFlip[j]));
        if (values.size > 1) return false;
      }
      return true;
    }
    colFlip[c] = 0;
    if (tryColumns(c + 1)) return true;
    colFlip[c] = 1;
    return tryColumns(c + 1);
  };
  return tryColumns(0);
}

