function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 5);
  // Build a solvable grid: every row is one pattern or its complement.
  const pattern = Array.from({ length: n }, () => (rand() < 0.5 ? 1 : 0));
  const grid = [];
  for (let r = 0; r < m; r++) {
    const flip = rand() < 0.5 ? 1 : 0;
    grid.push(pattern.map(v => v ^ flip));
  }
  const mode = rand();
  if (mode < 0.35) {
    // Spoil one cell, which usually makes the grid unsolvable.
    const r = Math.floor(rand() * m);
    const c = Math.floor(rand() * n);
    grid[r][c] ^= 1;
  } else if (mode < 0.5) {
    // A fully random grid.
    for (let r = 0; r < m; r++) for (let c = 0; c < n; c++) grid[r][c] = rand() < 0.5 ? 1 : 0;
  }
  return [grid];
}
